runs.sort(key=lambda r:r['t0'])
for i,r in enumerate(runs): r['t1']=runs[i+1]['t0'] if i+1<len(runs) else dt.datetime.max
lines=[]
for ln in open(SP+"/cluster.log",errors='replace'):
    ln=ansi.sub('',ln)
    if 'cancel_plan_fragment retired' not in ln: continue
