tot={}
for ts,reason,rel in lines:
    for r in runs:
        if r['t0']<=ts<r['t1']:
            k=(r['query'],r['run'],r['status']); d=tot.setdefault(k,{'n':0,'pos':0,'sum':0,'reasons':{}}); d['n']+=1; d['sum']+=rel; d['pos']+= rel>0; d['reasons'][reason]=d['reasons'].get(reason,0)+1; break
    else: print("UNMATCHED",ts,reason,rel)
perq={}
for k in sorted(tot, key=lambda k:(k[0],k[1])):
    d=tot[k]; print(k, d); 
    if k[2]=='fail': perq[k[0]]=perq.get(k[0],0)+d['sum']
print("per-query lease sums on failing runs:",perq, "total", sum(perq.values()))
print("passing runs with any released_leases>0:",[k for k,d in tot.items() if k[2]!='fail' and d['pos']>0])
print("runs:",len(runs),"pass:",sum(r['status']!='fail' for r in runs),"fail:",sum(r['status']=='fail' for r in runs))
